import { AdminPage } from "@/components/admin-page";

export default function Page() {
  return <AdminPage />;
}

"use client";

import { FilterIcon } from "lucide-react";
import { useState } from "react";
import {
  appliedFilters,
  defaultDirection,
  directionLabel,
  FILTERS,
  type FilterKey,
  hasActiveFilters,
  ROLES,
  roleLabel,
  SEATS_OPTIONS,
  type SeatsFilter,
  SORT_KEYS,
  type SortDirection,
  type SortOptionId,
  type SortState,
  STATUSES,
  type StatusFilter,
  sortLabel,
  statusLabel,
  TWO_FACTOR_OPTIONS,
  type TwoFactorFilter,
  type UserFilters,
  type UserSortKey,
} from "@/components/admin-filters";
import {
  Bound,
  DrilldownList,
  DrilldownRow,
  FilterOption,
  Options,
  StepHeader,
} from "@/components/drawer-parts";
import { statusLabels } from "@/components/mock-admin";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import {
  Drawer,
  DrawerContent,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer";
import { RadioGroup } from "@/components/ui/radio-group";
import {
  Stepper,
  StepperContent,
  StepperStep,
  useStepper,
} from "@/components/ui/stepper";

interface AdminFiltersDrawerProps {
  filters: UserFilters;
  onChange: (patch: Partial<UserFilters>) => void;
  onClear: () => void;
  onSortChange: (id: SortOptionId) => void;
  /**
   * `down` gives a bottom sheet, `right` a side panel. Rendered twice behind a
   * CSS fork rather than switched at runtime — see the note on the component.
   */
  placement: "down" | "right";
  sort: SortState | null;
}

/**
 * The filter surface, at every width.
 *
 * Not a mobile fallback any more: this table's filters live here on desktop
 * too, with the applied ones shown as chips in the toolbar. One surface means
 * there is no second tree to keep in step — the failure this block shipped
 * once, where three filters existed on desktop and nowhere else.
 *
 * The body is a `Stepper`: a menu of "label + current value" rows that drill
 * into one screen per filter. Same shape as `tickets-01`'s drawer and the
 * payments one, because a filter set too large for a toolbar is the same
 * problem wherever it appears.
 *
 * The *shell* differs by width — a bottom sheet on a phone, a right-hand panel
 * on a desktop, each the idiom for its size. `swipeDirection` is a prop rather
 * than a class, so this is rendered twice behind a CSS fork instead of being
 * switched at runtime: a `useMediaQuery` would have to guess on the server and
 * flip after hydration. Both shells are mounted, only one is in the
 * accessibility tree, and the date inputs take their ids from `placement`
 * because two mounted copies cannot share them.
 *
 * The rows are generated from `FILTERS`, so a new filter is one descriptor
 * rather than a row, a step, a hand-assigned index and a count that all have
 * to agree.
 *
 * Filters apply live; `Apply` only dismisses. There is no draft state to
 * reconcile, and on a large phone the table is visible behind the sheet.
 */
export function AdminFiltersDrawer({
  filters,
  onChange,
  onClear,
  onSortChange,
  placement,
  sort,
}: AdminFiltersDrawerProps) {
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);
  const activeCount = appliedFilters(filters).length;

  return (
    <Drawer
      onOpenChange={(isOpen) => {
        setOpen(isOpen);
        if (!isOpen) {
          setStep(0);
        }
      }}
      open={open}
      swipeDirection={placement}
    >
      {/* The count is the length of the same list the chips render, so the two
          cannot disagree — unlike the payments badge this block once carried,
          which counted the panel's filters while pills showed the rest. Sort
          lives in here too and is deliberately not counted: it is not a filter,
          and a badge that ticks up when you reorder a column is lying. */}
      <DrawerTrigger render={<Button variant="outline" />}>
        <FilterIcon className="size-4" />
        Filters
        {activeCount > 0 && <Badge variant="secondary">{activeCount}</Badge>}
      </DrawerTrigger>
      <DrawerContent variant={placement === "right" ? "floating" : "flush"}>
        <div className="mx-auto w-full max-w-sm">
          <Stepper onValueChange={setStep} value={step}>
            <StepperContent>
              <StepperStep>
                <DrawerHeader>
                  <DrawerTitle className="text-center">Filters</DrawerTitle>
                </DrawerHeader>
                <UserFilterMenu filters={filters} sort={sort} />
                <DrawerFooter>
                  {hasActiveFilters(filters) && (
                    <Button
                      className="w-full"
                      onClick={onClear}
                      variant="ghost"
                    >
                      Clear all
                    </Button>
                  )}
                  <Button className="w-full" onClick={() => setOpen(false)}>
                    Apply
                  </Button>
                </DrawerFooter>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Role" />
                <Options
                  onValueChange={(value) =>
                    onChange({ role: value as UserFilters["role"] })
                  }
                  value={filters.role}
                >
                  <FilterOption label={roleLabel("all")} value="all" />
                  {ROLES.map((role) => (
                    <FilterOption key={role} label={role} value={role} />
                  ))}
                </Options>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Status" />
                <Options
                  onValueChange={(value) =>
                    onChange({ status: value as StatusFilter })
                  }
                  value={filters.status}
                >
                  <FilterOption label={statusLabel("all")} value="all" />
                  {STATUSES.map((status) => (
                    <FilterOption
                      key={status}
                      label={statusLabels[status]}
                      value={status}
                    />
                  ))}
                </Options>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Seats" />
                <Options
                  onValueChange={(value) =>
                    onChange({ seats: value as SeatsFilter })
                  }
                  value={filters.seats}
                >
                  {SEATS_OPTIONS.map((option) => (
                    <FilterOption
                      key={option.id}
                      label={option.label}
                      value={option.id}
                    />
                  ))}
                </Options>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Two-factor" />
                <Options
                  onValueChange={(value) =>
                    onChange({ twoFactor: value as TwoFactorFilter })
                  }
                  value={filters.twoFactor}
                >
                  {TWO_FACTOR_OPTIONS.map((option) => (
                    <FilterOption
                      key={option.id}
                      label={option.label}
                      value={option.id}
                    />
                  ))}
                </Options>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Created" />
                <div className="grid grid-cols-2 gap-3 px-4 pb-4">
                  <Bound
                    id={`users-${placement}-created-after`}
                    label="After"
                    onChange={(value) => onChange({ createdAfter: value })}
                    value={filters.createdAfter}
                  />
                  <Bound
                    id={`users-${placement}-created-before`}
                    label="Before"
                    onChange={(value) => onChange({ createdBefore: value })}
                    value={filters.createdBefore}
                  />
                </div>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Sort" />
                <div className="pb-4">
                  <RadioGroup
                    className="gap-0 divide-y divide-border-muted"
                    onValueChange={(value) => {
                      if (value) {
                        onSortChange(
                          value === "none"
                            ? "none"
                            : (`${value}:${defaultDirection(
                                value as UserSortKey
                              )}` as SortOptionId)
                        );
                      }
                    }}
                    value={sort?.key ?? "none"}
                  >
                    <FilterOption label="Unsorted" value="none" />
                    {SORT_KEYS.map((option) => (
                      <FilterOption
                        key={option.id}
                        label={option.label}
                        value={option.id}
                      />
                    ))}
                  </RadioGroup>

                  {sort ? (
                    <RadioGroup
                      className="gap-0 divide-y divide-border-muted border-border-muted border-t"
                      onValueChange={(value) => {
                        if (value) {
                          onSortChange(
                            `${sort.key}:${
                              value as SortDirection
                            }` as SortOptionId
                          );
                        }
                      }}
                      value={sort.direction}
                    >
                      <FilterOption
                        label={directionLabel(sort.key, "asc")}
                        value="asc"
                      />
                      <FilterOption
                        label={directionLabel(sort.key, "desc")}
                        value="desc"
                      />
                    </RadioGroup>
                  ) : null}
                </div>
              </StepperStep>
            </StepperContent>
          </Stepper>
        </div>
      </DrawerContent>
    </Drawer>
  );
}

/**
 * The drilldown menu, generated from the descriptors so a row and its step
 * cannot disagree about their order. Sort is appended by hand because it is
 * not a filter and is not in `FILTERS`.
 */
function UserFilterMenu({
  filters,
  sort,
}: {
  filters: UserFilters;
  sort: SortState | null;
}) {
  const { goTo } = useStepper();
  const items: { key: FilterKey | "sort"; label: string; value: string }[] = [
    ...FILTERS.map((def) => ({
      key: def.key,
      label: def.label,
      value: def.value(filters) ?? def.empty,
    })),
    { key: "sort" as const, label: "Sort", value: sortLabel(sort) },
  ];

  return (
    <DrilldownList>
      {items.map((item, index) => (
        <DrilldownRow
          key={item.key}
          label={item.label}
          // Step 0 is the menu itself, so the first row is step 1.
          onClick={() => goTo(index + 1)}
          value={item.value}
        />
      ))}
    </DrilldownList>
  );
}

import {
  type Role,
  type Status,
  statusLabels,
  type User,
} from "@/components/mock-admin";

/**
 * The filter and sort vocabulary, owned in one place.
 *
 * The toolbar, the mobile drawer and the page all need the same option lists
 * and labels. `tickets-01` declares its lists twice — inline in the toolbar and
 * again in the drawer — which works until someone adds an option to one of
 * them. One owner, imported three ways, avoids that.
 *
 * Sort types live here too rather than in `admin-users-table.tsx`, so the
 * dependency runs one way: table and toolbar both import this, and this imports
 * neither.
 */

export type RoleFilter = "all" | Role;
export type StatusFilter = "all" | Status;

export type UserSortKey = "id" | "lastActive" | "name" | "role" | "seats";
export type SortDirection = "asc" | "desc";

export interface SortState {
  direction: SortDirection;
  key: UserSortKey;
}

/** "all" is rendered separately above the separator, so it is not in here. */
export const ROLES: readonly Role[] = ["Admin", "Billing", "Member", "Viewer"];
export const STATUSES: readonly Status[] = ["active", "invited", "suspended"];

export function roleLabel(role: RoleFilter): string {
  // Bare "All": the trigger and the drawer row both say Role already.
  return role === "all" ? "All" : role;
}

/** Shared by the table's Status cell and the detail view, so they cannot drift. */
export const STATUS_VARIANT: Record<
  Status,
  "default" | "outline" | "secondary"
> = {
  active: "secondary",
  invited: "outline",
  suspended: "outline",
};

export function statusLabel(status: StatusFilter): string {
  return status === "all" ? "All" : statusLabels[status];
}

// ---------------------------------------------------------------------------
// The filter model
// ---------------------------------------------------------------------------

export type SeatsFilter = "all" | "none" | "one" | "many";
export type TwoFactorFilter = "all" | "off" | "on";

export interface UserFilters {
  createdAfter: string;
  createdBefore: string;
  role: RoleFilter;
  search: string;
  seats: SeatsFilter;
  status: StatusFilter;
  twoFactor: TwoFactorFilter;
}

export const EMPTY_FILTERS: UserFilters = {
  createdAfter: "",
  createdBefore: "",
  role: "all",
  search: "",
  seats: "all",
  status: "all",
  twoFactor: "all",
};

export type FilterKey = "created" | "role" | "seats" | "status" | "twoFactor";

export interface FilterDef {
  /** The patch that resets this filter. */
  clear: Partial<UserFilters>;
  /** What the drawer row reads when nothing is set. */
  empty: string;
  key: FilterKey;
  label: string;
  /** The value, or `null` when the filter is unset. */
  value: (filters: UserFilters) => string | null;
}

export const SEATS_OPTIONS: readonly { id: SeatsFilter; label: string }[] = [
  { id: "all", label: "All" },
  { id: "none", label: "No seats" },
  { id: "one", label: "One seat" },
  { id: "many", label: "More than one" },
];

export const TWO_FACTOR_OPTIONS: readonly {
  id: TwoFactorFilter;
  label: string;
}[] = [
  { id: "all", label: "All" },
  { id: "on", label: "Enabled" },
  { id: "off", label: "Not enabled" },
];

function optionLabel(
  options: readonly { id: string; label: string }[],
  id: string
): string {
  return options.find((option) => option.id === id)?.label ?? "All";
}

/** An open-ended range still has to say which end it is open at. */
function rangeValue(after: string, before: string): string | null {
  if (after && before) {
    return `${after} – ${before}`;
  }
  if (after) {
    return `from ${after}`;
  }
  if (before) {
    return `to ${before}`;
  }
  return null;
}

/**
 * One descriptor per filter, and the only place a filter is declared.
 *
 * The chip row, the drawer's rows and steps, the active count and the
 * predicate all derive from this list, which is what keeps this layout and the
 * pills on the payments table two *renderings* of one model rather than two
 * implementations. It is also what removes the drawer's old hazard: its step
 * indices were hand-assigned integers in two places that had to be kept in
 * step with each other by hand.
 */
export const FILTERS: readonly FilterDef[] = [
  {
    clear: { role: "all" },
    empty: "All",
    key: "role",
    label: "Role",
    value: (f) => (f.role === "all" ? null : f.role),
  },
  {
    clear: { status: "all" },
    empty: "All",
    key: "status",
    label: "Status",
    value: (f) => (f.status === "all" ? null : statusLabels[f.status]),
  },
  {
    clear: { seats: "all" },
    empty: "All",
    key: "seats",
    label: "Seats",
    value: (f) =>
      f.seats === "all" ? null : optionLabel(SEATS_OPTIONS, f.seats),
  },
  {
    clear: { twoFactor: "all" },
    empty: "All",
    key: "twoFactor",
    label: "Two-factor",
    value: (f) =>
      f.twoFactor === "all"
        ? null
        : optionLabel(TWO_FACTOR_OPTIONS, f.twoFactor),
  },
  {
    clear: { createdAfter: "", createdBefore: "" },
    empty: "Any",
    key: "created",
    label: "Created",
    value: (f) => rangeValue(f.createdAfter, f.createdBefore),
  },
];

export function filterDef(key: FilterKey): FilterDef {
  const def = FILTERS.find((item) => item.key === key);
  if (!def) {
    throw new Error(`Unknown filter: ${key}`);
  }
  return def;
}

/** One entry per applied filter — the chip row, and the active count. */
export function appliedFilters(
  filters: UserFilters
): { def: FilterDef; value: string }[] {
  return FILTERS.flatMap((def) => {
    const value = def.value(filters);
    return value === null ? [] : [{ def, value }];
  });
}

/** Search is applied but is not a chip: the field itself shows its own state. */
export function hasActiveFilters(filters: UserFilters): boolean {
  return Boolean(filters.search.trim()) || appliedFilters(filters).length > 0;
}

// ---------------------------------------------------------------------------
// Matching
// ---------------------------------------------------------------------------

type UserMatcher = (user: User, filters: UserFilters) => boolean;

/** One predicate per filter, each returning `true` when the filter is unset. */
const MATCHERS: readonly UserMatcher[] = [
  (user, filters) => {
    const query = filters.search.trim().toLowerCase();
    return (
      !query ||
      user.name.toLowerCase().includes(query) ||
      user.email.toLowerCase().includes(query)
    );
  },
  (user, filters) => filters.role === "all" || user.role === filters.role,
  (user, filters) => filters.status === "all" || user.status === filters.status,
  (user, filters) => {
    if (filters.seats === "all") {
      return true;
    }
    if (filters.seats === "none") {
      return user.seats === 0;
    }
    return filters.seats === "one" ? user.seats === 1 : user.seats > 1;
  },
  (user, filters) =>
    filters.twoFactor === "all" ||
    user.twoFactor === (filters.twoFactor === "on"),
  // `createdAt` is an ISO date, so it compares as a string.
  (user, filters) =>
    !filters.createdAfter || user.createdAt >= filters.createdAfter,
  (user, filters) =>
    !filters.createdBefore || user.createdAt <= filters.createdBefore,
];

export function matchesUserFilters(user: User, filters: UserFilters): boolean {
  return MATCHERS.every((matches) => matches(user, filters));
}

// ---------------------------------------------------------------------------
// Sort
// ---------------------------------------------------------------------------

/**
 * A sort state flattened to a single string, so one `RadioGroup` can drive it.
 *
 * The toolbar and the table headers write the *same* `sort` state — picking
 * "Name Z–A" moves the header arrow, and clicking a header updates the
 * toolbar's label, with no syncing code. That only holds if every state the
 * headers can reach is nameable here, so all eight key × direction pairs are
 * listed even though a few are unlikely to be picked from the menu. A state the
 * headers could produce but the toolbar could not name would leave the radio
 * group with nothing selected.
 */
export type SortOptionId = "none" | `${UserSortKey}:${SortDirection}`;

/**
 * Sorting is two choices, not one: which column, then which way.
 *
 * The flat cross-product this replaces listed every pairing — eleven entries
 * for five columns — so changing direction meant finding your column again in
 * a list that had grown to hold both. Split, it is five plus two, and every
 * state the column headers can reach is expressible by construction rather
 * than by remembering to add the pairing.
 */
export const SORT_KEYS: readonly { id: UserSortKey; label: string }[] = [
  { id: "id", label: "ID" },
  { id: "name", label: "Name" },
  { id: "role", label: "Role" },
  { id: "seats", label: "Seats" },
  { id: "lastActive", label: "Last active" },
];

/**
 * What a direction means for the column it applies to. "Ascending" is
 * accurate and says nothing — "A–Z" and "Newest first" say what you will see.
 */
const DIRECTION_LABELS: Record<UserSortKey, Record<SortDirection, string>> = {
  id: { asc: "First added", desc: "Last added" },
  lastActive: { asc: "Oldest first", desc: "Newest first" },
  name: { asc: "A–Z", desc: "Z–A" },
  role: { asc: "A–Z", desc: "Z–A" },
  seats: { asc: "Fewest first", desc: "Most first" },
};

export function directionLabel(
  key: UserSortKey,
  direction: SortDirection
): string {
  return DIRECTION_LABELS[key][direction];
}

/**
 * The direction a column takes when it is first chosen. Names read forwards;
 * counts and dates are asked about from the large end, which is the same rule
 * the column headers use on a first click.
 */
export function defaultDirection(key: UserSortKey): SortDirection {
  return key === "name" || key === "role" ? "asc" : "desc";
}

export function sortKeyLabel(sort: SortState | null): string {
  return sort
    ? (SORT_KEYS.find((option) => option.id === sort.key)?.label ?? "Unsorted")
    : "Unsorted";
}
export function toSortOptionId(sort: SortState | null): SortOptionId {
  return sort ? `${sort.key}:${sort.direction}` : "none";
}

export function fromSortOptionId(id: SortOptionId): SortState | null {
  if (id === "none") {
    return null;
  }
  const [key, direction] = id.split(":");
  return { direction: direction as SortDirection, key: key as UserSortKey };
}

/** "Name (A–Z)" — the column, then what the order means for it. */
export function sortLabel(sort: SortState | null): string {
  return sort
    ? `${sortKeyLabel(sort)} (${directionLabel(sort.key, sort.direction)})`
    : "Unsorted";
}

"use client";

import { CopyIcon, EyeIcon, MoreHorizontalIcon } from "lucide-react";
import type { ReactNode } from "react";
import { AdminPaymentsToolbar } from "@/components/admin-payments-toolbar";
import {
  PAYMENT_STATUS_VARIANT,
  type Payment,
  paymentStatusLabels,
  paymentTypeLabels,
  truncateId,
} from "@/components/mock-payments";
import type {
  FilterKey,
  PaymentFilters,
  PaymentSortKey,
  SortOptionId,
  SortState,
} from "@/components/payment-filters";
import { ResultSummary } from "@/components/result-summary";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { CopyButton } from "@/components/ui/copy-button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Table,
  TableBody,
  TableCell,
  TableEmpty,
  TableHead,
  TableHeader,
  TableRow,
  TableSortButton,
} from "@/components/ui/table";
import {
  TablePagination,
  TablePaginationButtons,
  TablePaginationControls,
  TablePaginationInfo,
  TablePaginationPageSize,
  TablePaginationStatus,
} from "@/components/ui/table-pagination";

interface AdminPaymentsTableProps {
  addedFilters: readonly FilterKey[];
  filters: PaymentFilters;
  onFilterAdd: (key: FilterKey) => void;
  onFiltersChange: (patch: Partial<PaymentFilters>) => void;
  onFiltersClear: () => void;
  onOpenPayment: (id: string) => void;
  onPageIndexChange: (index: number) => void;
  onPageSizeChange: (size: number) => void;
  onSortChange: (id: SortOptionId) => void;
  pageCount: number;
  pageIndex: number;
  pageSize: number;
  rows: readonly Payment[];
  sort: SortState;
  totalCount: number;
}

export function AdminPaymentsTable({
  addedFilters,
  filters,
  onFilterAdd,
  onFiltersChange,
  onFiltersClear,
  onOpenPayment,
  onPageIndexChange,
  onPageSizeChange,
  onSortChange,
  pageCount,
  pageIndex,
  pageSize,
  rows,
  sort,
  totalCount,
}: AdminPaymentsTableProps) {
  return (
    <div className="flex w-full flex-col gap-6">
      {/* A real `h1`, and the page's only heading. `CardTitle` renders a div,
          so the section had no heading outline at all — a screen reader moving
          by headings found nothing here. It also sat inside the card, which
          made the panel announce itself rather than the page. */}
      <h1 className="font-semibold text-2xl tracking-tight">Payments</h1>

      <Card variant="outline">
        <CardContent className="flex flex-col gap-4">
          <AdminPaymentsToolbar
            added={addedFilters}
            filters={filters}
            onAdd={onFilterAdd}
            onChange={onFiltersChange}
            onClear={onFiltersClear}
          />

          <Table hoverable>
            <TableHeader>
              <TableRow>
                <TableHead className="w-[136px]">Payment ID</TableHead>
                {/* Only the four columns that actually sort carry a button.
                  `sortDirection` is omitted rather than passed as `null` on
                  the rest — `null` claims a column sorts and is merely
                  inactive, which would put `aria-sort` on eight headers when
                  four of them do nothing. */}
                <SortableHead
                  columnKey="playerEmail"
                  onSort={onSortChange}
                  sort={sort}
                >
                  Player
                </SortableHead>
                <SortableHead
                  columnKey="amount"
                  numeric
                  onSort={onSortChange}
                  sort={sort}
                >
                  Amount
                </SortableHead>
                <TableHead>Currency</TableHead>
                <TableHead>Type</TableHead>
                <SortableHead
                  columnKey="status"
                  onSort={onSortChange}
                  sort={sort}
                >
                  Status
                </SortableHead>
                <SortableHead
                  columnKey="createdAt"
                  onSort={onSortChange}
                  sort={sort}
                >
                  Created
                </SortableHead>
                <TableHead>Finished</TableHead>
                {/* No visible label: the column is one icon wide, and "Actions"
                    above it would size the column from the header rather than
                    from the control. */}
                <TableHead className="w-12">
                  <span className="sr-only">Actions</span>
                </TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {rows.length === 0 ? (
                <TableEmpty colSpan={9}>
                  No payments match these filters.
                </TableEmpty>
              ) : (
                rows.map((row) => (
                  <TableRow className="group/row" key={row.id}>
                    <TableCell>
                      <div className="flex items-center gap-1">
                        {/* Middle-truncated: the head and tail are what someone
                          eyeballs against another system, and the full value is
                          one click away on the clipboard or the record. */}
                        <button
                          className="cursor-pointer rounded-sm font-mono text-muted-foreground text-xs hover:underline focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2"
                          onClick={() => onOpenPayment(row.id)}
                          type="button"
                        >
                          {truncateId(row.id)}
                        </button>
                        <CopyButton size="icon-xs" value={row.id} />
                      </div>
                    </TableCell>
                    <TableCell>
                      <span className="truncate">{row.playerEmail}</span>
                    </TableCell>
                    <TableCell numeric>{row.amount}</TableCell>
                    <TableCell>
                      <Badge variant="outline">{row.currency}</Badge>
                    </TableCell>
                    <TableCell>
                      <Badge variant="outline">
                        {paymentTypeLabels[row.type]}
                      </Badge>
                    </TableCell>
                    <TableCell>
                      <Badge variant={PAYMENT_STATUS_VARIANT[row.status]}>
                        {paymentStatusLabels[row.status]}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-muted-foreground">
                      {row.createdAt}
                    </TableCell>
                    <TableCell className="text-muted-foreground">
                      {row.finishedAt ?? "-"}
                    </TableCell>
                    <TableCell>
                      <RowActions
                        onOpen={() => onOpenPayment(row.id)}
                        paymentId={row.id}
                      />
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>

          {/* Composed rather than props-driven: the info slot only renders a
              selection count from props, and this table has no selection. The
              parts are otherwise the default composition. */}
          <TablePagination pageCount={pageCount} pageIndex={pageIndex}>
            <TablePaginationInfo>
              <ResultSummary
                noun={["payment", "payments"]}
                pageIndex={pageIndex}
                pageSize={pageSize}
                rowCount={rows.length}
                totalCount={totalCount}
              />
            </TablePaginationInfo>
            <TablePaginationControls>
              <TablePaginationPageSize
                onValueChange={onPageSizeChange}
                value={pageSize}
              />
              <TablePaginationStatus
                pageCount={pageCount}
                pageIndex={pageIndex}
              />
              <TablePaginationButtons
                onPageIndexChange={onPageIndexChange}
                pageCount={pageCount}
                pageIndex={pageIndex}
              />
            </TablePaginationControls>
          </TablePagination>
        </CardContent>
      </Card>
    </div>
  );
}

/**
 * A sortable column header.
 *
 * Clicking an inactive column sorts it descending first — for dates and
 * amounts the interesting end is the large one, and starting ascending would
 * make every first click a wasted one.
 */
function SortableHead({
  children,
  columnKey,
  numeric,
  onSort,
  sort,
}: {
  children: ReactNode;
  columnKey: PaymentSortKey;
  numeric?: boolean;
  onSort: (id: SortOptionId) => void;
  sort: SortState;
}) {
  const active = sort.key === columnKey;
  const direction = active ? sort.direction : null;

  return (
    <TableHead numeric={numeric} sortDirection={direction}>
      <TableSortButton
        direction={direction}
        onClick={() =>
          onSort(
            `${columnKey}:${active && sort.direction === "desc" ? "asc" : "desc"}`
          )
        }
      >
        {children}
      </TableSortButton>
    </TableHead>
  );
}

/**
 * Row actions, in a trailing menu rather than a hover-revealed button.
 *
 * The button it replaces was unreachable on touch: there is no hover, and
 * `focus-visible:opacity-100` only rescues a keyboard. A ledger is also where
 * per-row actions accumulate — refund, export receipt, open the player — and a
 * menu absorbs those where a row of inline buttons cannot.
 *
 * "Copy payment ID" duplicates the icon button beside the id deliberately:
 * that one is the fast path for a value the table shows truncated, this one is
 * the labelled path for anyone who would not read an unlabelled icon.
 */
function RowActions({
  onOpen,
  paymentId,
}: {
  onOpen: () => void;
  paymentId: string;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button size="icon-sm" variant="ghost" />}>
        <MoreHorizontalIcon />
        <span className="sr-only">
          Actions for payment {truncateId(paymentId)}
        </span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-44">
        <DropdownMenuGroup>
          <DropdownMenuItem onClick={onOpen}>
            <EyeIcon />
            View details
          </DropdownMenuItem>
          <DropdownMenuItem
            onClick={async () => {
              // No "Copied" state to hold — the menu closes on click — so this
              // needs none of what `CopyButton` manages beyond awaiting the
              // write and not throwing where the clipboard is unavailable.
              try {
                await navigator.clipboard.writeText(paymentId);
              } catch {
                // Insecure context or permission denied; nothing to undo.
              }
            }}
          >
            <CopyIcon />
            Copy payment ID
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { SearchIcon, XIcon } from "lucide-react";
import {
  AddFilterMenu,
  PaymentFilterPill,
} from "@/components/payment-filter-pills";
import {
  addableKeys,
  type FilterKey,
  hasActiveFilters,
  type PaymentFilters,
  visibleKeys,
} from "@/components/payment-filters";
import { PaymentFiltersDrawer } from "@/components/payment-filters-drawer";
import { Button } from "@/components/ui/button";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";

interface AdminPaymentsToolbarProps {
  added: readonly FilterKey[];
  filters: PaymentFilters;
  onAdd: (key: FilterKey) => void;
  onChange: (patch: Partial<PaymentFilters>) => void;
  onClear: () => void;
}

/**
 * Search, then one self-describing pill per filter, then `+ Add filter`.
 *
 * Each pill names its own dimension — `Action: Deposit` rather than `Deposit`
 * — which is what lets the control double as the record of what is applied.
 * That is why there is no chip row underneath: a chip repeating a pill you can
 * already see is a second copy of the same fact, and the two can drift.
 *
 * Six pills at once would wrap before anyone had used one, so only the two
 * most common cuts are permanent and the rest are added on demand. A filter
 * that holds a value always shows its pill regardless — see `visibleKeys`.
 *
 * Sorting is not here: the column headers own it, the way `admin-01`'s users
 * table does. A sort control in the filter row reads as a filter, and the
 * header is where someone looks to reorder a column anyway.
 *
 * Below `sm` the pills fold away and the drawer carries the whole filter set,
 * the same fork the users toolbar uses. A row of pills becomes a column of
 * pills on a phone, which buries the table it is filtering.
 */
export function AdminPaymentsToolbar({
  added,
  filters,
  onAdd,
  onChange,
  onClear,
}: AdminPaymentsToolbarProps) {
  const visible = visibleKeys(filters, added);
  const addable = addableKeys(filters, added);

  return (
    <div className="flex flex-wrap items-center gap-2">
      <InputGroup className="min-w-0 flex-1 sm:max-w-xs">
        <InputGroupAddon align="inline-start">
          <SearchIcon />
        </InputGroupAddon>
        <InputGroupInput
          aria-label="Search payments by email"
          onChange={(event) => onChange({ email: event.target.value })}
          placeholder="Search email…"
          type="search"
          value={filters.email}
        />
      </InputGroup>

      <div className="hidden flex-wrap items-center gap-2 sm:flex">
        {visible.map((key) => (
          <PaymentFilterPill
            filters={filters}
            key={key}
            onChange={onChange}
            onPin={onAdd}
            pillKey={key}
          />
        ))}

        <AddFilterMenu keys={addable} onAdd={onAdd} />

        {hasActiveFilters(filters) && (
          // Muted at rest: undoing everything is the least likely thing you
          // came here to do, and it sits next to the control you probably did.
          // It brightens on hover so it still answers when pointed at.
          <Button
            className="text-muted-foreground hover:text-foreground"
            onClick={onClear}
            variant="ghost"
          >
            <XIcon />
            Clear all
          </Button>
        )}
      </div>

      <div className="shrink-0 sm:hidden">
        <PaymentFiltersDrawer
          filters={filters}
          onChange={onChange}
          onClear={onClear}
        />
      </div>
    </div>
  );
}

