  TablePaginationInfo,
  TablePaginationPageSize,
  TablePaginationStatus,
} from "@/components/ui/table-pagination";

// Re-exported for the page, which composes this table. The types themselves
// live in `admin-filters.ts` so the dependency runs one way.
export type {
  SortDirection,
  SortState,
  UserSortKey,
} from "@/components/admin-filters";

const columns = [
  // Explicit width: the table distributes free space, and an id needs only
  // enough room for its own text — matching `tickets-01`'s ID column.
  {
    icon: HashIcon,
    key: "id",
    label: "ID",
    numeric: false,
    width: "w-[116px]",
  },
  { key: "name", label: "User", numeric: false },
  { key: "role", label: "Role", numeric: false },
  { key: "seats", label: "Seats", numeric: true },
  { key: "lastActive", label: "Last active", numeric: false },
] as const;

interface AdminUsersTableProps {
  filters: UserFilters;
  onClearSelection: () => void;
  onFiltersChange: (patch: Partial<UserFilters>) => void;
  onFiltersClear: () => void;
  onOpenUser: (id: string) => void;
  onPageIndexChange: (index: number) => void;
  onPageSizeChange: (size: number) => void;
  onSort: (key: UserSortKey) => void;
  onSortChange: (id: SortOptionId) => void;
  onToggleAll: (checked: boolean) => void;
  onToggleRow: (id: string) => void;
  pageCount: number;
  pageIndex: number;
  pageSize: number;
  rows: readonly User[];
  selected: ReadonlySet<string>;
  sort: SortState | null;
  totalCount: number;
}

export function AdminUsersTable({
  onClearSelection,
  onPageIndexChange,
  onPageSizeChange,
  filters,
  onFiltersChange,
  onFiltersClear,
  onOpenUser,
  onSort,
  onSortChange,
  onToggleAll,
  onToggleRow,
  pageCount,
  pageIndex,
  pageSize,
  rows,
  selected,
  sort,
  totalCount,
}: AdminUsersTableProps) {
  // Binary rather than tri-state: keystone's Checkbox has no indeterminate
  // variant, and re-implementing tickets-01's custom mixed-state button here
  // would duplicate a workaround rather than share one.
  const allOnPageSelected =
    rows.length > 0 && rows.every((row) => selected.has(row.id));

  return (
    <>
      {/* A real `h1`, above the card rather than inside it. `CardTitle` renders
          a div, so this section had no heading outline at all, and a title in
          the card made the panel announce itself rather than the page. */}
      <div className="flex w-full flex-col gap-6">
        <h1 className="font-semibold text-2xl tracking-tight">Users</h1>

        <Card variant="outline">
          <CardContent className="flex flex-col gap-4">
            <AdminUsersToolbar
              filters={filters}
              onChange={onFiltersChange}
              onClear={onFiltersClear}
              onSortChange={onSortChange}
              sort={sort}
            />

            <Table hoverable>
              <TableHeader>
                <TableRow>
                  <TableHead className="w-10">
                    <Checkbox
                      aria-label="Select all users on this page"
                      checked={allOnPageSelected}
                      onCheckedChange={(checked) =>
                        onToggleAll(checked === true)
                      }
                    />
                  </TableHead>
                  {columns.map((column) => (
                    <TableHead
                      className={"width" in column ? column.width : undefined}
                      key={column.key}
                      numeric={column.numeric}
                      sortDirection={
                        sort?.key === column.key ? sort.direction : null
                      }
                    >
                      <TableSortButton
                        direction={
                          sort?.key === column.key ? sort.direction : null
                        }
                        onClick={() => onSort(column.key)}
                      >
                        {"icon" in column ? (
                          <column.icon className="size-3.5 shrink-0" />
                        ) : null}
                        {column.label}
                      </TableSortButton>
                    </TableHead>
                  ))}
                  {/* Not sortable, so no sortDirection at all — omitting it means
                      no aria-sort, where `null` would claim the column sorts. */}
                  <TableHead>Status</TableHead>
                  {/* One icon wide, so no visible label: "Actions" above it
                      would size the column from the header. */}
                  <TableHead className="w-12">
                    <span className="sr-only">Actions</span>
                  </TableHead>
                </TableRow>
              </TableHeader>

              <TableBody>
                {rows.length === 0 ? (
                  <TableEmpty colSpan={columns.length + 3}>
                    <p className="py-10 text-center text-muted-foreground text-sm">
                      No users match these filters.
                    </p>
                  </TableEmpty>
                ) : (
                  rows.map((row) => (
                    <TableRow
                      className="group/row"
                      data-state={selected.has(row.id) ? "selected" : undefined}
                      key={row.id}
                    >
                      <TableCell>
                        <Checkbox
                          aria-label={`Select ${row.name}`}
                          checked={selected.has(row.id)}
                          onCheckedChange={() => onToggleRow(row.id)}
                        />
                      </TableCell>
                      <TableCell>
                        <span className="font-mono text-muted-foreground text-xs">
                          {row.id}
                        </span>
                      </TableCell>
                      <TableCell>
                        <div className="min-w-0">
                          <button
                            className="cursor-pointer rounded-sm text-left font-medium hover:underline focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2"
                            onClick={() => onOpenUser(row.id)}
                            type="button"
                          >
                            {row.name}
                          </button>
                          <div className="truncate text-muted-foreground text-xs">
                            {row.email}
                          </div>
                        </div>
                      </TableCell>
                      <TableCell className="text-muted-foreground">
                        {row.role}
                      </TableCell>
                      <TableCell numeric>{row.seats}</TableCell>
                      <TableCell className="text-muted-foreground">
                        {row.lastActive}
                      </TableCell>
                      <TableCell>
                        <Badge variant={STATUS_VARIANT[row.status]}>
                          {statusLabels[row.status]}
                        </Badge>
                      </TableCell>
                      <TableCell>
                        <UserRowActions
                          name={row.name}
                          onOpen={() => onOpenUser(row.id)}
                          userId={row.id}
                        />
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>

            {/* Composed: the info slot's only props-driven content is a
                selection count, which the `SelectionBar` already states — and
                states at every width, where this slot is `hidden lg:block`. */}
            <TablePagination pageCount={pageCount} pageIndex={pageIndex}>
              <TablePaginationInfo>
                <ResultSummary
                  noun={["user", "users"]}
                  pageIndex={pageIndex}
                  pageSize={pageSize}
                  rowCount={rows.length}
                  totalCount={totalCount}
                />
              </TablePaginationInfo>
              <TablePaginationControls>
                <TablePaginationPageSize
                  onValueChange={onPageSizeChange}
                  options={[5, 10, 20, 50]}
                  value={pageSize}
                />
                <TablePaginationStatus
                  pageCount={pageCount}
                  pageIndex={pageIndex}
                />
                <TablePaginationButtons
                  onPageIndexChange={onPageIndexChange}
                  pageCount={pageCount}
                  pageIndex={pageIndex}
                />
              </TablePaginationControls>
            </TablePagination>
          </CardContent>
        </Card>
      </div>

      <SelectionBar open={selected.size > 0}>
        <SelectionBarClose onClick={onClearSelection} />
        <SelectionBarGroup>
          <SelectionBarLabel>
            {selected.size} {selected.size === 1 ? "user" : "users"} selected
          </SelectionBarLabel>
        </SelectionBarGroup>
        <SelectionBarButton>Change role</SelectionBarButton>
        <SelectionBarButton>Resend invite</SelectionBarButton>
        <SelectionBarSeparator />
        <SelectionBarButton tone="destructive">Suspend</SelectionBarButton>
      </SelectionBar>
    </>
  );
}

/** How much of the result set is on screen. */
/**
 * Row actions, in a trailing menu rather than a hover-revealed button.
 *
 * The button it replaces was unreachable on touch — `focus-visible` rescues a
 * keyboard, not a finger. The name stays clickable, so opening a record keeps
 * its one-click path.
 */
function UserRowActions({
  name,
  onOpen,
  userId,
}: {
  name: string;
  onOpen: () => void;
  userId: string;
}) {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button size="icon-sm" variant="ghost" />}>
        <MoreHorizontalIcon />
        <span className="sr-only">Actions for {name}</span>
      </DropdownMenuTrigger>
      <DropdownMenuContent align="end" className="min-w-44">
        <DropdownMenuGroup>
          <DropdownMenuItem onClick={onOpen}>
            <EyeIcon />
            View details
          </DropdownMenuItem>
          <DropdownMenuItem
            onClick={async () => {
              try {
                await navigator.clipboard.writeText(userId);
              } catch {
                // Insecure context or permission denied; nothing to undo.
              }
            }}
          >
            <CopyIcon />
            Copy user ID
          </DropdownMenuItem>
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { ArrowUpDownIcon, SearchIcon, XIcon } from "lucide-react";
import type { ReactNode } from "react";
import {
  appliedFilters,
  defaultDirection,
  directionLabel,
  hasActiveFilters,
  SORT_KEYS,
  type SortDirection,
  type SortOptionId,
  type SortState,
  sortKeyLabel,
  type UserFilters,
  type UserSortKey,
} from "@/components/admin-filters";
import { AdminFiltersDrawer } from "@/components/admin-filters-drawer";
import { FilterChip } from "@/components/filter-chip";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuLabel,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  InputGroup,
  InputGroupAddon,
  InputGroupInput,
} from "@/components/ui/input-group";

interface AdminUsersToolbarProps {
  filters: UserFilters;
  onChange: (patch: Partial<UserFilters>) => void;
  onClear: () => void;
  onSortChange: (id: SortOptionId) => void;
  sort: SortState | null;
}

/**
 * Search, one Filters button, one Sort — and what is applied as a chip row.
 *
 * The alternative to the payments table's inline pills, and the right shape
 * for a different job. Pills suit a table you sit in front of flipping a
 * filter at a time: two clicks to change one, and you can see what is
 * filterable without opening anything. This suits a table you filter once and
 * then read: the chip row *is* the answer to "what is applied", where a row of
 * pills makes you scan six to find the two that are set.
 *
 * It also removes a fork. The drawer is the filter surface at every width, so
 * there is no desktop tree and mobile tree to keep in step — which is how this
 * block once shipped filters that were reachable on no phone at all.
 *
 * Sort keeps its own trigger at `sm+` and its drawer step below. Sorting is
 * not filtering, and burying a one-click control on desktop to make the layout
 * look tidier would be a regression.
 */
export function AdminUsersToolbar({
  filters,
  onChange,
  onClear,
  onSortChange,
  sort,
}: AdminUsersToolbarProps) {
  const applied = appliedFilters(filters);

  return (
    <div className="flex flex-col gap-3">
      <div className="flex flex-row items-center gap-2 sm:gap-3">
        <InputGroup className="min-w-0 flex-1 sm:max-w-xs">
          <InputGroupAddon align="inline-start">
            <SearchIcon />
          </InputGroupAddon>
          <InputGroupInput
            aria-label="Search users"
            onChange={(event) => onChange({ search: event.target.value })}
            placeholder="Search name or email…"
            type="search"
            value={filters.search}
          />
        </InputGroup>

        {/* Two shells, one body — a bottom sheet on a phone and a right-hand
            panel on a desktop. Only one is in the accessibility tree at a
            time, so `getByRole` and a screen reader both see exactly one. */}
        <div className="shrink-0 sm:hidden">
          <AdminFiltersDrawer
            filters={filters}
            onChange={onChange}
            onClear={onClear}
            onSortChange={onSortChange}
            placement="down"
            sort={sort}
          />
        </div>
        <div className="hidden shrink-0 sm:block">
          <AdminFiltersDrawer
            filters={filters}
            onChange={onChange}
            onClear={onClear}
            onSortChange={onSortChange}
            placement="right"
            sort={sort}
          />
        </div>

        <div className="hidden items-center gap-2 sm:flex">
          <DropdownMenu>
            <DropdownMenuTrigger render={<Button variant="outline" />}>
              <ArrowUpDownIcon />
              <TriggerLabel>Sort</TriggerLabel>
              {sortKeyLabel(sort)}
              {sort ? (
                <span className="font-normal text-muted-foreground">
                  ({directionLabel(sort.key, sort.direction)})
                </span>
              ) : null}
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" className="min-w-52">
              <DropdownMenuGroup>
                <DropdownMenuLabel>Sort by</DropdownMenuLabel>
                <DropdownMenuRadioGroup
                  onValueChange={(value) =>
                    onSortChange(
                      value === "none"
                        ? "none"
                        : (`${value}:${defaultDirection(
                            value as UserSortKey
                          )}` as SortOptionId)
                    )
                  }
                  value={sort?.key ?? "none"}
                >
                  <DropdownMenuRadioItem value="none">
                    Unsorted
                  </DropdownMenuRadioItem>
                  {SORT_KEYS.map((option) => (
                    <DropdownMenuRadioItem key={option.id} value={option.id}>
                      {option.label}
                    </DropdownMenuRadioItem>
                  ))}
                </DropdownMenuRadioGroup>
              </DropdownMenuGroup>

              {sort ? (
                <>
                  <DropdownMenuSeparator />
                  <DropdownMenuGroup>
                    <DropdownMenuRadioGroup
                      onValueChange={(value) =>
                        onSortChange(
                          `${sort.key}:${
                            value as SortDirection
                          }` as SortOptionId
                        )
                      }
                      value={sort.direction}
                    >
                      <DropdownMenuRadioItem value="asc">
                        {directionLabel(sort.key, "asc")}
                      </DropdownMenuRadioItem>
                      <DropdownMenuRadioItem value="desc">
                        {directionLabel(sort.key, "desc")}
                      </DropdownMenuRadioItem>
                    </DropdownMenuRadioGroup>
                  </DropdownMenuGroup>
                </>
              ) : null}
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      </div>

      {/* Keyed to `hasActiveFilters`, not to the chips: search is applied state
          with no chip of its own — the field shows it — so gating on chips
          alone left a searched table with nothing to clear it from.

          At every width, because on a phone this is the one place a filter can
          be seen and removed without reopening the drawer. */}
      {hasActiveFilters(filters) && (
        <div className="flex flex-wrap items-center gap-1.5">
          {applied.map(({ def, value }) => (
            <FilterChip
              key={def.key}
              label={def.label}
              onRemove={() => onChange(def.clear)}
              value={value}
            />
          ))}
          {/* `xs`, so it matches the 24px chips it sits among rather than the
              40px controls above them. It is in the chip row, not the control
              row, and the sweep in `e2e/control-heights.spec.ts` only compares
              controls that share a visual row. */}
          <Button
            className="text-muted-foreground hover:text-foreground"
            onClick={onClear}
            size="xs"
            variant="ghost"
          >
            <XIcon />
            Clear all
          </Button>
        </div>
      )}
    </div>
  );
}

/**
 * The dimension a filter trigger acts on, muted ahead of its value.
 *
 * A second copy rather than a shared part: presentational code in two blocks
 * is the same demo twice, and installable copies are flat, so two blocks
 * shipping one basename would overwrite each other.
 */
function TriggerLabel({ children }: { children: ReactNode }) {
  return <span className="font-normal text-muted-foreground">{children}:</span>;
}

/**
 * Named value formatters.
 *
 * Panels take `format="money"` rather than a `formatter` function, because the
 * installed entry point of this block is `app/dashboard/page.tsx` — a server
 * component. A function cannot cross that boundary: React rejects it at render
 * time. A block that taught `formatter={(v) => …}` would teach a pattern that
 * breaks the moment someone installs it.
 */

export type ValueFormat = "compact" | "money" | "number" | "percent";

const NUMBER = new Intl.NumberFormat("en-US");
const COMPACT = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 1,
  notation: "compact",
});
const MONEY = new Intl.NumberFormat("en-US", {
  currency: "USD",
  maximumFractionDigits: 0,
  style: "currency",
});
const PERCENT = new Intl.NumberFormat("en-US", {
  maximumFractionDigits: 1,
  style: "percent",
});

const FORMATTERS: Record<ValueFormat, (value: number) => string> = {
  compact: (value) => COMPACT.format(value),
  money: (value) => MONEY.format(value),
  number: (value) => NUMBER.format(value),
  percent: (value) => PERCENT.format(value),
};

/**
 * `null` stays `null` all the way to the em dash.
 *
 * Coercing with `Number(value)` turns an absent measurement into `0`, which
 * then prints as "$0" or "0%" — a reading the data never took. The distinction
 * between "nothing happened" and "we did not measure" is worth the extra
 * branch.
 */
export function toValue(value: unknown): number | null {
  if (value == null) {
    return null;
  }
  const numeric = typeof value === "number" ? value : Number(value);
  return Number.isFinite(numeric) ? numeric : null;
}

export function formatValue(
  value: unknown,
  format: ValueFormat = "number"
): string {
  const numeric = toValue(value);
  return numeric === null ? "—" : FORMATTERS[format](numeric);
}

/**
 * The chart layer for this block, ported from shadcn's `chart.tsx`.
 *
 * Vendored into the block rather than added to `@keystoneui/react` on purpose:
 * it needs recharts, and the library stays dependency-light. A block may carry
 * npm dependencies of its own -- `tickets-01` already does, with `@dnd-kit`.
 *
 * Most of the value is the ~20 `[&_.recharts-*]` overrides on `ChartContainer`,
 * which make recharts' hardcoded `#ccc` and `#fff` marks respect the theme.
 * That list is archaeology, not something to re-derive.
 *
 * Two changes from upstream shadcn, both load-bearing:
 *
 *  - `aspect-auto`, not `aspect-video`. Under an explicit pixel height the
 *    upstream class produces a 462px floor and a horizontal document
 *    scrollbar.
 *  - `min-w-0` added, because a chart is a grid or flex child and those
 *    default to `min-content`.
 *
 * `ChartLegend`/`ChartLegendContent` are dropped: `series-legend.tsx` ships a
 * toggleable legend, so recharts' own `<Legend>` never mounts, and leaving the
 * dead path in would mean two legends to pick between.
 */
"use client";

import * as React from "react";
import type { TooltipValueType } from "recharts";
import * as RechartsPrimitive from "recharts";
import { cn } from "@/lib/utils";

/**
 * Format: { THEME_NAME: CSS_SELECTOR }.
 *
 * Upstream emits a `.dark [data-chart=id]` block as well, so a config can carry
 * a literal colour per mode. Ours never does -- `seriesColor()` returns a
 * `var(--chart-N)` *reference*, and the token already re-steps for dark -- so
 * the second block would be textually identical to the first. One entry.
 */
const THEMES = { light: "" } as const;

const INITIAL_DIMENSION = { width: 320, height: 200 } as const;
type TooltipNameType = number | string;

export type ChartConfig = Record<
  string,
  {
    label?: React.ReactNode;
    icon?: React.ComponentType;
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
>;

type ChartContextProps = {
  config: ChartConfig;
};

const ChartContext = React.createContext<ChartContextProps | null>(null);

function useChart() {
  const context = React.useContext(ChartContext);

  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />");
  }

  return context;
}

function ChartContainer({
  id,
  className,
  children,
  config,
  initialDimension = INITIAL_DIMENSION,
  ...props
}: React.ComponentProps<"div"> & {
  config: ChartConfig;
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"];
  initialDimension?: {
    width: number;
    height: number;
  };
}) {
  const uniqueId = React.useId();
  const chartId = `chart-${id ?? uniqueId.replace(/:/g, "")}`;

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "flex aspect-auto min-w-0 justify-center text-xs [&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground [&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50 [&_.recharts-curve.recharts-tooltip-cursor]:stroke-border [&_.recharts-dot[stroke='#fff']]:stroke-transparent [&_.recharts-layer]:outline-hidden [&_.recharts-polar-grid_[stroke='#ccc']]:stroke-border [&_.recharts-radial-bar-background-sector]:fill-muted [&_.recharts-rectangle.recharts-tooltip-cursor]:fill-muted [&_.recharts-reference-line_[stroke='#ccc']]:stroke-border [&_.recharts-sector[stroke='#fff']]:stroke-transparent [&_.recharts-sector]:outline-hidden [&_.recharts-surface]:outline-hidden",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer
          initialDimension={initialDimension}
        >
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

const ChartStyle = ({ id, config }: { id: string; config: ChartConfig }) => {
  const colorConfig = Object.entries(config).filter(
    ([, config]) => config.theme ?? config.color
  );

  if (!colorConfig.length) {
    return null;
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ??
      itemConfig.color;
    return color ? `  --color-${key}: ${color};` : null;
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  );
};

const ChartTooltip = RechartsPrimitive.Tooltip;

function ChartTooltipContent({
  active,
  payload,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  label,
  labelFormatter,
  labelClassName,
  formatter,
  color,
  nameKey,
  labelKey,
}: React.ComponentProps<typeof RechartsPrimitive.Tooltip> &
  React.ComponentProps<"div"> & {
    hideLabel?: boolean;
    hideIndicator?: boolean;
    indicator?: "line" | "dot" | "dashed";
    nameKey?: string;
    labelKey?: string;
  } & Omit<
    RechartsPrimitive.DefaultTooltipContentProps<
      TooltipValueType,
      TooltipNameType
    >,
    "accessibilityLayer"
  >) {
  const { config } = useChart();

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null;
    }

    const [item] = payload;
    const key = `${labelKey ?? item?.dataKey ?? item?.name ?? "value"}`;
    const itemConfig = getPayloadConfigFromPayload(config, item, key);
    const value =
      !labelKey && typeof label === "string"
        ? (config[label]?.label ?? label)
        : itemConfig?.label;

    if (labelFormatter) {
      return (
        <div className={cn("font-medium", labelClassName)}>
          {labelFormatter(value, payload)}
        </div>
      );
    }

    if (!value) {
      return null;
    }

    return <div className={cn("font-medium", labelClassName)}>{value}</div>;
  }, [
    label,
    labelFormatter,
    payload,
    hideLabel,
    labelClassName,
    config,
    labelKey,
  ]);

  if (!(active && payload?.length)) {
    return null;
  }

  const nestLabel = payload.length === 1 && indicator !== "dot";

  return (
    <div
      className={cn(
        "grid min-w-32 items-start gap-1.5 rounded-lg border border-border/50 bg-background px-2.5 py-1.5 text-xs shadow-xl",
        className
      )}
    >
      {nestLabel ? null : tooltipLabel}
      <div className="grid gap-1.5">
        {payload
          .filter((item) => item.type !== "none")
          .map((item, index) => {
            const key = `${nameKey ?? item.name ?? item.dataKey ?? "value"}`;
            const itemConfig = getPayloadConfigFromPayload(config, item, key);
            const indicatorColor = color ?? item.payload?.fill ?? item.color;

            return (
              <div
                key={index}
                className={cn(
                  "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                  indicator === "dot" && "items-center"
                )}
              >
                {formatter && item?.value !== undefined && item.name ? (
                  formatter(item.value, item.name, item, index, item.payload)
                ) : (
                  <>
                    {itemConfig?.icon ? (
                      <itemConfig.icon />
                    ) : (
                      !hideIndicator && (
                        <div
                          className={cn(
                            "shrink-0 rounded-[2px] border-(--color-border) bg-(--color-bg)",
                            {
                              "h-2.5 w-2.5": indicator === "dot",
                              "w-1": indicator === "line",
                              "w-0 border-[1.5px] border-dashed bg-transparent":
                                indicator === "dashed",
                              "my-0.5": nestLabel && indicator === "dashed",
                            }
                          )}
                          style={
                            {
                              "--color-bg": indicatorColor,
                              "--color-border": indicatorColor,
                            } as React.CSSProperties
                          }
                        />
                      )
                    )}
                    <div
                      className={cn(
                        "flex flex-1 justify-between leading-none",
                        nestLabel ? "items-end" : "items-center"
                      )}
                    >
                      <div className="grid gap-1.5">
                        {nestLabel ? tooltipLabel : null}
                        <span className="text-muted-foreground">
                          {itemConfig?.label ?? item.name}
                        </span>
                      </div>
                      {item.value != null && (
                        <span className="font-medium font-mono text-foreground tabular-nums">
                          {typeof item.value === "number"
                            ? item.value.toLocaleString()
                            : String(item.value)}
                        </span>
                      )}
                    </div>
                  </>
                )}
              </div>
            );
          })}
      </div>
    </div>
  );
}

function getPayloadConfigFromPayload(
  config: ChartConfig,
  payload: unknown,
  key: string
) {
  if (typeof payload !== "object" || payload === null) {
    return;
  }

  const payloadPayload =
    "payload" in payload &&
    typeof payload.payload === "object" &&
    payload.payload !== null
      ? payload.payload
      : undefined;

  let configLabelKey: string = key;

  if (
    key in payload &&
    typeof payload[key as keyof typeof payload] === "string"
  ) {
    configLabelKey = payload[key as keyof typeof payload] as string;
  } else if (
    payloadPayload &&
    key in payloadPayload &&
    typeof payloadPayload[key as keyof typeof payloadPayload] === "string"
  ) {
    configLabelKey = payloadPayload[
      key as keyof typeof payloadPayload
    ] as string;
  }

  return configLabelKey in config ? config[configLabelKey] : config[key];
}

