      <span className="font-medium text-sm">{label}</span>
      <span className="ml-auto inline-flex min-w-0 items-center gap-2 text-muted-foreground text-sm">
        <span className="truncate">{value}</span>
        <ChevronRightIcon className="size-4 shrink-0" />
      </span>
    </button>
  );
}

/** The list wrapper the drilldown rows sit in. */
export function DrilldownList({ children }: { children: ReactNode }) {
  return <div className="divide-y divide-border-muted">{children}</div>;
}

/** A radio list styled as drawer rows rather than as a form control group. */
export function Options({
  children,
  onValueChange,
  value,
}: {
  children: ReactNode;
  onValueChange: (value: string) => void;
  value: string;
}) {
  return (
    <div className="pb-4">
      <RadioGroup
        className="gap-0 divide-y divide-border-muted"
        onValueChange={(next) => {
          if (next) {
            onValueChange(next as string);
          }
        }}
        value={value}
      >
        {children}
      </RadioGroup>
    </div>
  );
}

export function FilterOption({
  label,
  value,
}: {
  label: string;
  value: string;
}) {
  return (
    // biome-ignore lint/a11y/noLabelWithoutControl: control is inside label
    <label className="flex h-12 cursor-pointer items-center gap-3 px-4">
      <RadioGroupItem value={value} />
      <span className="text-sm">{label}</span>
    </label>
  );
}

/**
 * One end of a range. `type` defaults to text because most bounds are numeric
 * strings; the date filters pass `type="date"`.
 */
export function Bound({
  id,
  label,
  onChange,
  placeholder,
  type = "text",
  value,
}: {
  id: string;
  label: string;
  onChange: (value: string) => void;
  placeholder?: string;
  type?: string;
  value: string;
}) {
  return (
    <div className="flex flex-col gap-1.5">
      <Label className="text-muted-foreground" htmlFor={id}>
        {label}
      </Label>
      <Input
        id={id}
        inputMode={type === "text" ? "decimal" : undefined}
        onChange={(event) => onChange(event.target.value)}
        placeholder={placeholder}
        type={type}
        value={value}
      />
    </div>
  );
}

"use client";

import { XIcon } from "lucide-react";
import { Badge } from "@/components/ui/badge";

export interface FilterChipProps {
  label: string;
  onRemove: () => void;
  value: string;
}

/**
 * An applied filter: `Role: Admin ✕`.
 *
 * Built on `Badge`, not `Tag`, and the reason is semantic before it is
 * practical. `Tag` extends Base UI's Toggle — it is a *selectable token*, with
 * `aria-pressed`, a pointer cursor and a hover fill. An applied filter is not
 * selectable: it is a label with one action attached. Rendering it as a toggle
 * would announce a pressed state that means nothing and offer an affordance
 * that does nothing.
 *
 * The practical half follows from the same fact. Because `Tag` and
 * `TagGroupItem` are buttons, putting `TagRemove` inside one emits
 * `<button>…<button/></button>` — invalid, and the label stays focusable.
 * `Badge` is a polymorphic `<span>`, so the remove button nests validly.
 *
 * It does borrow `Tag`'s height. `Badge` defaults to 20px, which is right for
 * a status badge with nothing to hit and cramped for one carrying a target.
 *
 * The chip is the only representation of this filter's state: the control that
 * sets it lives in the drawer. That is the condition under which a chip is
 * right — where the control is visible, as on the payments table, a chip
 * repeating it is a second copy of one fact and the two can drift.
 *
 * `Remove ${label} filter`, not a bare "Remove": four chips announcing
 * "Remove" leave a screen reader to work out which from context it does not
 * have, the same rule the row-action triggers follow.
 */
export function FilterChip({ label, onRemove, value }: FilterChipProps) {
  return (
    <Badge
      className="h-6 gap-1 pr-1 pl-2.5"
      data-filter-chip=""
      variant="secondary"
    >
      <span className="font-normal text-muted-foreground">{label}:</span>
      {value}
      <button
        aria-label={`Remove ${label} filter`}
        className="relative -my-px -me-0.5 inline-flex size-4 shrink-0 cursor-pointer items-center justify-center rounded-full text-muted-foreground transition-colors before:absolute before:-inset-2 hover:text-foreground focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2"
        onClick={onRemove}
        type="button"
      >
        <XIcon className="size-3" />
      </button>
    </Badge>
  );
}

"use client";

import { ChevronDownIcon } from "lucide-react";
import { Button, type ButtonProps } from "@/components/ui/button";
import { cn } from "@/lib/utils";

export interface FilterTriggerProps extends ButtonProps {
  /** Emphasises the pill when the filter holds a value. */
  active?: boolean;
  /**
   * The dimension being filtered, shown muted ahead of the value. Omit it when
   * the value names its own dimension — a date range reads as "Last 24h", and
   * "Period: Last 24h" only repeats itself.
   */
  label?: string;
}

/**
 * A filter pill: `Action: Deposit`, with a chevron.
 *
 * Written once rather than inlined at each call site for three reasons, none
 * of them purely cosmetic. The muted label is what separates the dimension
 * from the value at a glance. The `active` treatment is what lets you scan a
 * row of eight pills for the two that are doing something. And the chevron is
 * the one the trigger primitives disagree about — `DropdownMenuTrigger` draws
 * none, `SelectTrigger` and `ComboboxTrigger` each draw their own — so putting
 * it here is what stops a row of pills from disagreeing about its own
 * affordance depending on which primitive each one happens to use.
 *
 * Used through `render`, which is how the rest of the block composes triggers:
 *
 * ```tsx
 * <DropdownMenuTrigger render={<FilterTrigger label="Action" />}>
 *   Deposit
 * </DropdownMenuTrigger>
 * ```
 */
export function FilterTrigger({
  active = false,
  children,
  className,
  label,
  ...props
}: FilterTriggerProps) {
  return (
    <Button
      className={cn(
        "gap-1.5",
        // No border or ring for the applied state. Anything bright enough to
        // scan a row of pills for reads as focus, which is a control claiming
        // the keyboard is on it. The distinction lives in the value instead:
        // an unset pill renders its "All" muted, a set one renders its value
        // at full strength — the same way a placeholder differs from an entry.
        className
      )}
      data-active={active || undefined}
      // Not `data-slot`: used through `render`, the trigger primitive merges
      // its own props over this element's and stamps its own slot, so a
      // `data-slot` here is silently discarded. This attribute is the one
      // thing that can identify a pill in the DOM.
      data-filter-pill=""
      variant="outline"
      {...props}
    >
      {label ? (
        <span className="font-normal text-muted-foreground" data-pill-label="">
          {label}:
        </span>
      ) : null}
      {children}
      <ChevronDownIcon className="text-muted-foreground" />
    </Button>
  );
}

"use client";

import { PlusIcon } from "lucide-react";
import type { ReactNode } from "react";
import { Bound } from "@/components/drawer-parts";
import { FilterTrigger } from "@/components/filter-trigger";
import { CURRENCIES, type Currency } from "@/components/mock-payments";
import {
  type FilterKey,
  filterDef,
  type PaymentFilters,
  PROVIDER_OPTIONS,
  providerLabel,
  STATUS_OPTIONS,
  statusLabel,
  TYPE_OPTIONS,
  typeLabel,
} from "@/components/payment-filters";
import { Button } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuCheckboxItem,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuRadioGroup,
  DropdownMenuRadioItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";

interface PillProps {
  filters: PaymentFilters;
  onChange: (patch: Partial<PaymentFilters>) => void;
  /**
   * Pins the pill to the row. Clearing calls it so that a pill which was only
   * showing because it held a value — one set from the mobile drawer, say —
   * does not vanish under the cursor the moment it is emptied.
   */
  onPin: (key: FilterKey) => void;
}

/**
 * One pill per visible filter.
 *
 * A pill is never removed from inside its own menu. Setting one back to `All`
 * leaves it on the row on purpose — taking the control out from under the
 * cursor mid-interaction is worse than a pill that reads `All` — and an empty
 * pill has nothing to remove that `Clear all` does not already handle. So the
 * menu holds options and, once something is chosen, a `Clear`.
 */
export function PaymentFilterPill({
  filters,
  onChange,
  onPin,
  pillKey,
}: PillProps & { pillKey: FilterKey }) {
  const def = filterDef(pillKey);
  // Every change made through a pill also pins it. Without this a pill that
  // is only on the row because it holds a value — one set from the mobile
  // drawer — disappears the moment you empty it, taking the control out from
  // under the cursor. Emptying a filter is the one moment you are most likely
  // to want to set it to something else.
  const change = (patch: Partial<PaymentFilters>) => {
    onChange(patch);
    onPin(pillKey);
  };
  const value = def.value(filters);
  const shared = {
    active: value !== null,
    label: def.label,
  };
  // Unset reads as a placeholder rather than a value, which is what separates
  // the pills doing something from the ones merely present.
  const body = <PillValue empty={def.empty} value={value} />;

  if (pillKey === "created" || pillKey === "amount") {
    return <RangePill filters={filters} onChange={change} pillKey={pillKey} />;
  }

  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<FilterTrigger {...shared} />}>
        {body}
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="min-w-44">
        <DropdownMenuGroup>
          {pillKey === "currencies" ? (
            <CurrencyItems filters={filters} onChange={change} />
          ) : (
            <RadioItems filters={filters} onChange={change} pillKey={pillKey} />
          )}
        </DropdownMenuGroup>
        {/* Only the multi-select earns a footer: a single-select's list
            already starts with "All", which is its own clear. */}
        {pillKey === "currencies" && (
          <MenuFooter
            count={filters.currencies.length}
            onClear={() => change(def.clear)}
          />
        )}
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

function RadioItems({
  filters,
  onChange,
  pillKey,
}: {
  filters: PaymentFilters;
  onChange: (patch: Partial<PaymentFilters>) => void;
  pillKey: FilterKey;
}) {
  if (pillKey === "type") {
    return (
      <DropdownMenuRadioGroup
        onValueChange={(value) =>
          onChange({ type: value as PaymentFilters["type"] })
        }
        value={filters.type}
      >
        {TYPE_OPTIONS.map((option) => (
          <DropdownMenuRadioItem key={option} value={option}>
            {typeLabel(option)}
          </DropdownMenuRadioItem>
        ))}
      </DropdownMenuRadioGroup>
    );
  }

  if (pillKey === "status") {
    return (
      <DropdownMenuRadioGroup
        onValueChange={(value) =>
          onChange({ status: value as PaymentFilters["status"] })
        }
        value={filters.status}
      >
        {STATUS_OPTIONS.map((option) => (
          <DropdownMenuRadioItem key={option} value={option}>
            {statusLabel(option)}
          </DropdownMenuRadioItem>
        ))}
      </DropdownMenuRadioGroup>
    );
  }

  return (
    <DropdownMenuRadioGroup
      onValueChange={(value) =>
        onChange({ provider: value as PaymentFilters["provider"] })
      }
      value={filters.provider}
    >
      {PROVIDER_OPTIONS.map((option) => (
        <DropdownMenuRadioItem key={option} value={option}>
          {providerLabel(option)}
        </DropdownMenuRadioItem>
      ))}
    </DropdownMenuRadioGroup>
  );
}

/**
 * `DropdownMenuCheckboxItem` keeps the menu open on click, which is what a
 * multi-select wants — picking three currencies should not cost three trips.
 */
function CurrencyItems({
  filters,
  onChange,
}: {
  filters: PaymentFilters;
  onChange: (patch: Partial<PaymentFilters>) => void;
}) {
  const toggle = (currency: Currency) =>
    onChange({
      currencies: filters.currencies.includes(currency)
        ? filters.currencies.filter((item) => item !== currency)
        : [...filters.currencies, currency],
    });

  return (
    <>
      {CURRENCIES.map((currency) => (
        <DropdownMenuCheckboxItem
          checked={filters.currencies.includes(currency)}
          key={currency}
          onCheckedChange={() => toggle(currency)}
          variant="control"
        >
          {currency}
        </DropdownMenuCheckboxItem>
      ))}
    </>
  );
}

/**
 * Ranges need two fields at once, so they open a `Popover` rather than a menu.
 * A menu is a list of choices; a pair of bounds is a tiny form.
 */
function RangePill({
  filters,
  onChange,
  pillKey,
}: Omit<PillProps, "onPin"> & { pillKey: FilterKey }) {
  const def = filterDef(pillKey);
  const value = def.value(filters);
  const isDate = pillKey === "created";

  return (
    <Popover>
      <PopoverTrigger
        render={<FilterTrigger active={value !== null} label={def.label} />}
      >
        <PillValue empty={def.empty} value={value} />
      </PopoverTrigger>
      <PopoverContent align="start" className="w-72">
        <div className="flex flex-col gap-3">
          <div className="grid grid-cols-2 gap-3">
            <Bound
              id={`${pillKey}-min`}
              label={isDate ? "After" : "Min"}
              onChange={(next) =>
                onChange(isDate ? { createdAfter: next } : { amountMin: next })
              }
              placeholder={isDate ? undefined : "0.00"}
              type={isDate ? "date" : "text"}
              value={isDate ? filters.createdAfter : filters.amountMin}
            />
            <Bound
              id={`${pillKey}-max`}
              label={isDate ? "Before" : "Max"}
              onChange={(next) =>
                onChange(isDate ? { createdBefore: next } : { amountMax: next })
              }
              placeholder={isDate ? undefined : "Any"}
              type={isDate ? "date" : "text"}
              value={isDate ? filters.createdBefore : filters.amountMax}
            />
          </div>
          {value !== null && (
            <div className="flex justify-end">
              <Button
                onClick={() => onChange(def.clear)}
                size="xs"
                variant="ghost"
              >
                Clear
              </Button>
            </div>
          )}
        </div>
      </PopoverContent>
    </Popover>
  );
}

/**
 * The menu's footer: what is held on the left, the way to empty it on the
 * right.
 *
 * It exists only while the filter holds a value. An empty filter has nothing
 * to say and nothing to undo, and a footer offering an action that would do
 * nothing is just a row you have to read past to reach the options.
 *
 * The count is the point of it: the pill has room for the first value and a
 * tally of the rest — "BTC, +2" — so the footer is where that number gets
 * spelled out.
 */
function MenuFooter({
  count,
  onClear,
}: {
  count: number;
  onClear: () => void;
}) {
  if (count === 0) {
    return null;
  }

  return (
    <>
      <DropdownMenuSeparator />
      {/* A uniform `p-1.5` is what makes every gap here come out equal. The
          content's own `p-1` already insets 4px on the right and bottom and
          the separator's `my-1` gives 4px above, so adding the same 6px on
          all four sides lands the button 10px from each — and lands the count
          at the same 10px an item's text starts from (4px content + `px-1.5`),
          so it lines up with the options above it. */}
      <div className="flex items-center justify-between gap-3 p-1.5">
        <span className="text-muted-foreground text-xs">{count} selected</span>
        <Button onClick={onClear} size="xs" variant="ghost">
          Clear
        </Button>
      </div>
    </>
  );
}

/**
 * The pill's value, in its own slot so the set and unset cases are the same
 * element rather than a span and a bare text node — which is what lets a test
 * compare their colours at all.
 */
function PillValue({ empty, value }: { empty: string; value: string | null }) {
  return (
    <span
      className={value === null ? "font-normal text-muted-foreground" : ""}
      data-pill-value=""
    >
      {value ?? empty}
    </span>
  );
}

/** The `+ Add filter` menu, holding whatever is not already on the toolbar. */
export function AddFilterMenu({
  keys,
  onAdd,
}: {
  keys: readonly FilterKey[];
  onAdd: (key: FilterKey) => void;
}): ReactNode {
  if (keys.length === 0) {
    return null;
  }

  return (
    <DropdownMenu>
      {/* A lucide `Plus` rather than a literal "+": next to the `X` on Clear
          all, a text glyph would sit at a different weight and baseline. */}
      <DropdownMenuTrigger render={<Button variant="ghost" />}>
        <PlusIcon />
        Add filter
      </DropdownMenuTrigger>
      <DropdownMenuContent align="start" className="min-w-44">
        <DropdownMenuGroup>
          {keys.map((key) => (
            <DropdownMenuItem key={key} onClick={() => onAdd(key)}>
              {filterDef(key).label}
            </DropdownMenuItem>
          ))}
        </DropdownMenuGroup>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

"use client";

import { FilterIcon } from "lucide-react";
import type { ReactNode } from "react";
import { useState } from "react";
import {
  Bound,
  DrilldownList,
  DrilldownRow,
  FilterOption,
  Options,
  StepHeader,
} from "@/components/drawer-parts";
import { CURRENCIES } from "@/components/mock-payments";
import {
  FILTERS,
  filterDef,
  hasActiveFilters,
  type PaymentFilters,
  PROVIDER_OPTIONS,
  providerLabel,
  STATUS_OPTIONS,
  statusLabel,
  TYPE_OPTIONS,
  typeLabel,
} from "@/components/payment-filters";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import {
  Drawer,
  DrawerContent,
  DrawerFooter,
  DrawerHeader,
  DrawerTitle,
  DrawerTrigger,
} from "@/components/ui/drawer";
import {
  Stepper,
  StepperContent,
  StepperStep,
  useStepper,
} from "@/components/ui/stepper";

interface PaymentFiltersDrawerProps {
  filters: PaymentFilters;
  onChange: (patch: Partial<PaymentFilters>) => void;
  onClear: () => void;
}

/**
 * The mobile half of the payments toolbar.
 *
 * The same bottom sheet + `Stepper` drilldown the users drawer uses, and for
 * the same reason: a menu of "label + current value" rows that open one screen
 * per filter is how a phone handles a filter set that will not fit, and a
 * block should not answer that question twice in two different ways. This
 * started life as a scrolling column of selects — a desktop panel put on a
 * phone — which is exactly the reinvention the users drawer warns against.
 *
 * No `swipeDirection`: the primitive's default is `down`, which is what
 * supplies the bottom-sheet geometry and the drag handle. No `variant` either
 * — `floating` only applies from `md` up, and this drawer is `sm:hidden`, so
 * it could never have taken effect.
 *
 * Filters apply live; `Apply` only dismisses. Same as the users drawer.
 */
export function PaymentFiltersDrawer({
  filters,
  onChange,
  onClear,
}: PaymentFiltersDrawerProps) {
  const [open, setOpen] = useState(false);
  const [step, setStep] = useState(0);
  const activeCount = FILTERS.filter(
    (def) => def.value(filters) !== null
  ).length;

  return (
    <Drawer
      onOpenChange={(isOpen) => {
        setOpen(isOpen);
        if (!isOpen) {
          setStep(0);
        }
      }}
      open={open}
    >
      {/* The count is on the trigger because the pills are hidden at this
          width — without it a filtered table gives no sign of being filtered. */}
      <DrawerTrigger render={<Button variant="outline" />}>
        <FilterIcon className="size-4" />
        Filters
        {activeCount > 0 && <Badge variant="secondary">{activeCount}</Badge>}
      </DrawerTrigger>
      <DrawerContent>
        <div className="mx-auto w-full max-w-sm">
          <Stepper onValueChange={setStep} value={step}>
            <StepperContent>
              <StepperStep>
                <DrawerHeader>
                  <DrawerTitle className="text-center">Filters</DrawerTitle>
                </DrawerHeader>
                <PaymentFilterMenu filters={filters} />
                <DrawerFooter>
                  {hasActiveFilters(filters) && (
                    <Button
                      className="w-full"
                      onClick={onClear}
                      variant="ghost"
                    >
                      Clear all
                    </Button>
                  )}
                  <Button className="w-full" onClick={() => setOpen(false)}>
                    Apply
                  </Button>
                </DrawerFooter>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Action" />
                <Options
                  onValueChange={(value) =>
                    onChange({ type: value as PaymentFilters["type"] })
                  }
                  value={filters.type}
                >
                  {TYPE_OPTIONS.map((option) => (
                    <FilterOption
                      key={option}
                      label={typeLabel(option)}
                      value={option}
                    />
                  ))}
                </Options>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Status" />
                <Options
                  onValueChange={(value) =>
                    onChange({ status: value as PaymentFilters["status"] })
                  }
                  value={filters.status}
                >
                  {STATUS_OPTIONS.map((option) => (
                    <FilterOption
                      key={option}
                      label={statusLabel(option)}
                      value={option}
                    />
                  ))}
                </Options>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Currency" />
                {/* Checkboxes, not radios: this is the one multi-select in the
                    set, so it is the one screen you do not leave per pick. */}
                <div className="divide-y divide-border-muted pb-4">
                  {CURRENCIES.map((currency) => (
                    // biome-ignore lint/a11y/noLabelWithoutControl: control is inside label
                    <label
                      className="flex h-12 cursor-pointer items-center gap-3 px-4"
                      key={currency}
                    >
                      <Checkbox
                        checked={filters.currencies.includes(currency)}
                        onCheckedChange={() =>
                          onChange({
                            currencies: filters.currencies.includes(currency)
                              ? filters.currencies.filter(
                                  (item) => item !== currency
                                )
                              : [...filters.currencies, currency],
                          })
                        }
                      />
                      <span className="text-sm">{currency}</span>
                    </label>
                  ))}
                </div>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Provider" />
                <Options
                  onValueChange={(value) =>
                    onChange({ provider: value as PaymentFilters["provider"] })
                  }
                  value={filters.provider}
                >
                  {PROVIDER_OPTIONS.map((option) => (
                    <FilterOption
                      key={option}
                      label={providerLabel(option)}
                      value={option}
                    />
                  ))}
                </Options>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Created" />
                <Bounds>
                  <Bound
                    id="drawer-created-after"
                    label="After"
                    onChange={(value) => onChange({ createdAfter: value })}
                    type="date"
                    value={filters.createdAfter}
                  />
                  <Bound
                    id="drawer-created-before"
                    label="Before"
                    onChange={(value) => onChange({ createdBefore: value })}
                    type="date"
                    value={filters.createdBefore}
                  />
                </Bounds>
              </StepperStep>

              <StepperStep>
                <StepHeader onBack={() => setStep(0)} title="Amount" />
                <Bounds>
                  <Bound
                    id="drawer-amount-min"
                    label="Min"
                    onChange={(value) => onChange({ amountMin: value })}
                    placeholder="0.00"
                    value={filters.amountMin}
                  />
                  <Bound
                    id="drawer-amount-max"
                    label="Max"
                    onChange={(value) => onChange({ amountMax: value })}
                    placeholder="Any"
                    value={filters.amountMax}
                  />
                </Bounds>
              </StepperStep>
            </StepperContent>
          </Stepper>
        </div>
      </DrawerContent>
    </Drawer>
  );
}

const MENU_STEPS = [
  { key: "type", step: 1 },
  { key: "status", step: 2 },
  { key: "currencies", step: 3 },
  { key: "provider", step: 4 },
  { key: "created", step: 5 },
  { key: "amount", step: 6 },
] as const;

/**
 * The drilldown menu. Every row's value comes from the same `FILTERS`
 * descriptor the desktop pills read, so a row and its pill cannot disagree
 * about what is applied.
 */
function PaymentFilterMenu({ filters }: { filters: PaymentFilters }) {
  const { goTo } = useStepper();

  const items = MENU_STEPS.map(({ key, step }) => {
    const def = filterDef(key);
    return {
      label: def.label,
      step,
      // A row has room the pill does not, so a multi-select says what the
      // number counts rather than leaving a bare "3".
      value:
        key === "currencies" && filters.currencies.length > 1
          ? `${filters.currencies.length} selected`
          : (def.value(filters) ?? def.empty),
    };
  });

  return (
    <DrilldownList>
      {items.map((item) => (
        <DrilldownRow
          key={item.step}
          label={item.label}
          onClick={() => goTo(item.step)}
          value={item.value}
        />
      ))}
    </DrilldownList>
  );
}

function Bounds({ children }: { children: ReactNode }) {
  return <div className="grid grid-cols-2 gap-3 px-4 pb-4">{children}</div>;
}

import {
  type Currency,
  type Payment,
  type PaymentStatus,
  type PaymentType,
  PROVIDERS,
  type Provider,
  paymentStatusLabels,
} from "@/components/mock-payments";

/**
 * The payments filter vocabulary, owned in one place.
 *
 * Every filter is a pill that names its own dimension — `Action: Deposit`, not
 * `Deposit`. A bare value turns ambiguous the moment it sits beside another
 * one: is "Deposit" a type or a status? Naming the dimension also lets the
 * control double as the record of what is applied, which is why there is no
 * separate chip row here. A chip repeating a visible pill is a second
 * representation of the same fact, and two representations can disagree.
 *
 * `FILTERS` below is the single source of truth that the toolbar pills, the
 * add-filter menu and the mobile drawer all read.
 */

export type TypeFilter = "all" | PaymentType;
export type StatusFilter = "all" | PaymentStatus;
export type ProviderFilter = "all" | Provider;

export interface PaymentFilters {
  amountMax: string;
  amountMin: string;
  createdAfter: string;
  createdBefore: string;
  currencies: readonly Currency[];
  email: string;
  provider: ProviderFilter;
  status: StatusFilter;
  type: TypeFilter;
}

export const EMPTY_FILTERS: PaymentFilters = {
  amountMax: "",
  amountMin: "",
  createdAfter: "",
  createdBefore: "",
  currencies: [],
  email: "",
  provider: "all",
  status: "all",
  type: "all",
};

export const STATUS_OPTIONS: readonly StatusFilter[] = [
  "all",
  "completed",
  "in-progress",
  "failed",
];

export const TYPE_OPTIONS: readonly TypeFilter[] = [
  "all",
  "deposit",
  "cashout",
];

export const PROVIDER_OPTIONS: readonly ProviderFilter[] = [
  "all",
  ...PROVIDERS,
];

/**
 * The unset value reads as a bare "All" because the pill already says which
 * dimension it belongs to — "Action: All types" would say it twice.
 */
const TYPE_LABELS: Record<TypeFilter, string> = {
  all: "All",
  cashout: "Cashout",
  deposit: "Deposit",
};

export function typeLabel(type: TypeFilter): string {
  return TYPE_LABELS[type];
}

export function statusLabel(status: StatusFilter): string {
  return status === "all" ? "All" : paymentStatusLabels[status];
}

export function providerLabel(provider: ProviderFilter): string {
  return provider === "all" ? "All" : provider;
}

// ---------------------------------------------------------------------------
// Sort
// ---------------------------------------------------------------------------

export type PaymentSortKey = "amount" | "createdAt" | "playerEmail" | "status";
export type SortDirection = "asc" | "desc";

export interface SortState {
  direction: SortDirection;
  key: PaymentSortKey;
}

export type SortOptionId = `${PaymentSortKey}:${SortDirection}`;

export const SORT_OPTIONS: readonly { id: SortOptionId; label: string }[] = [
  { id: "createdAt:desc", label: "Created, newest" },
  { id: "createdAt:asc", label: "Created, oldest" },
  { id: "amount:desc", label: "Amount, largest" },
  { id: "amount:asc", label: "Amount, smallest" },
  { id: "playerEmail:asc", label: "Player A–Z" },
  { id: "playerEmail:desc", label: "Player Z–A" },
  { id: "status:asc", label: "Status A–Z" },
  { id: "status:desc", label: "Status Z–A" },
];

export const DEFAULT_SORT: SortState = { direction: "desc", key: "createdAt" };

export function toSortOptionId(sort: SortState): SortOptionId {
  return `${sort.key}:${sort.direction}`;
}

export function fromSortOptionId(id: SortOptionId): SortState {
  const [key, direction] = id.split(":");
  return { direction: direction as SortDirection, key: key as PaymentSortKey };
}

export function sortLabel(sort: SortState): string {
  const id = toSortOptionId(sort);
  return SORT_OPTIONS.find((option) => option.id === id)?.label ?? "Sort";
}

// ---------------------------------------------------------------------------
// Matching
// ---------------------------------------------------------------------------

type PaymentMatcher = (payment: Payment, filters: PaymentFilters) => boolean;

/**
 * One predicate per filter, each returning `true` when the filter is unset.
 *
 * A list rather than a single predicate with nine early returns: a filter set
 * is exactly a conjunction, and writing it as one keeps each rule readable on
 * its own and makes adding the tenth a one-line change.
 */
const MATCHERS: readonly PaymentMatcher[] = [
  (payment, filters) => {
    const query = filters.email.trim().toLowerCase();
    return !query || payment.playerEmail.toLowerCase().includes(query);
  },
  (payment, filters) =>
    filters.currencies.length === 0 ||
    filters.currencies.includes(payment.currency),
  (payment, filters) => filters.type === "all" || payment.type === filters.type,
  (payment, filters) =>
    filters.status === "all" || payment.status === filters.status,
  (payment, filters) =>
    filters.provider === "all" || payment.provider === filters.provider,
  // The timestamps are ISO, so the date half compares as a string.
  (payment, filters) =>
    !filters.createdAfter ||
    payment.createdAt.slice(0, 10) >= filters.createdAfter,
  (payment, filters) =>
    !filters.createdBefore ||
    payment.createdAt.slice(0, 10) <= filters.createdBefore,
  (payment, filters) =>
    !filters.amountMin || Number(payment.amount) >= Number(filters.amountMin),
  (payment, filters) =>
    !filters.amountMax || Number(payment.amount) <= Number(filters.amountMax),
];

export function matchesPaymentFilters(
  payment: Payment,
  filters: PaymentFilters
): boolean {
  return MATCHERS.every((matches) => matches(payment, filters));
}

export function sortPayments(
  rows: readonly Payment[],
  sort: SortState
): Payment[] {
  const factor = sort.direction === "asc" ? 1 : -1;
  return [...rows].sort((a, b) =>
    sort.key === "amount"
      ? (Number(a.amount) - Number(b.amount)) * factor
      : a[sort.key].localeCompare(b[sort.key]) * factor
  );
}

// ---------------------------------------------------------------------------
// The pills
// ---------------------------------------------------------------------------

export type FilterKey =
  | "amount"
  | "created"
  | "currencies"
  | "provider"
  | "status"
  | "type";

export interface FilterDef {
  /** The patch that resets this filter. */
  clear: Partial<PaymentFilters>;
  /**
   * What the pill reads when nothing is set. "All" suits a set of options;
   * a range is not a set, so its bounds read as "Any".
   */
  empty: string;
  key: FilterKey;
  /** The dimension, shown muted ahead of the value. */
  label: string;
  /** The value, or `null` when the filter is unset. */
  value: (filters: PaymentFilters) => string | null;
}

/**
 * Two filters sit on the toolbar permanently because they are the cuts people
 * take first. The rest are added on demand: every pill costs horizontal room,
 * and a row that always carries all six wraps before anyone has used one.
 */
export const DEFAULT_KEYS: readonly FilterKey[] = ["type", "status"];

export const FILTERS: readonly FilterDef[] = [
  {
    clear: { type: "all" },
    empty: "All",
    key: "type",
    label: "Action",
    value: (f) => (f.type === "all" ? null : typeLabel(f.type)),
  },
  {
    clear: { status: "all" },
    empty: "All",
    key: "status",
    label: "Status",
    value: (f) => (f.status === "all" ? null : statusLabel(f.status)),
  },
  {
    clear: { currencies: [] },
    empty: "All",
    key: "currencies",
    label: "Currency",
    // The first selection plus a count of the rest: "BTC, +2". A bare "3"
    // says how many without saying which, and four tickers side by side stop
    // being scannable and start being a sentence.
    value: (f) => {
      if (f.currencies.length === 0) {
        return null;
      }
      return f.currencies.length === 1
        ? f.currencies[0]
        : `${f.currencies[0]}, +${f.currencies.length - 1}`;
    },
  },
  {
    clear: { provider: "all" },
    empty: "All",
    key: "provider",
    label: "Provider",
    value: (f) => (f.provider === "all" ? null : f.provider),
  },
  {
    clear: { createdAfter: "", createdBefore: "" },
    empty: "Any",
    key: "created",
    label: "Created",
    value: (f) => rangeValue(f.createdAfter, f.createdBefore),
  },
  {
    clear: { amountMax: "", amountMin: "" },
    empty: "Any",
    key: "amount",
    label: "Amount",
    value: (f) => rangeValue(f.amountMin, f.amountMax),
  },
];

/** An open-ended range still has to say which end it is open at. */
function rangeValue(min: string, max: string): string | null {
  if (min && max) {
    return `${min} – ${max}`;
  }
  if (min) {
    return `from ${min}`;
  }
  if (max) {
    return `to ${max}`;
  }
  return null;
}

export function filterDef(key: FilterKey): FilterDef {
  const def = FILTERS.find((item) => item.key === key);
  if (!def) {
    throw new Error(`Unknown filter: ${key}`);
  }
  return def;
}

/**
 * Which pills the toolbar shows, in the order it shows them: the permanent
 * ones, then the ones added by hand in the order they were added, then — the
 * load-bearing term — any filter that holds a value without having been asked
 * for.
 *
 * That last group is what makes applied state impossible to hide. A filter
 * with a value and no pill is exactly the failure the old chip row existed to
 * paper over; here it cannot happen, rather than merely being tested for. It
 * is reachable through the mobile drawer, which sets filters that were never
 * added as pills.
 *
 * The ordering matters as much as the membership. Filtering `FILTERS` in
 * declaration order put each new pill in its canonical slot instead of at the
 * end — add Amount then Currency and Currency landed in front of it, nowhere
 * near the `+ Add filter` button you were just looking at.
 */
export function visibleKeys(
  filters: PaymentFilters,
  added: readonly FilterKey[]
): FilterKey[] {
  const pinned = [...DEFAULT_KEYS];
  const chosen = added.filter((key) => !pinned.includes(key));
  const valued = FILTERS.filter(
    (def) =>
      def.value(filters) !== null &&
      !(pinned.includes(def.key) || chosen.includes(def.key))
  ).map((def) => def.key);

  return [...pinned, ...chosen, ...valued];
}

/** Filters still available to add — the add-filter menu's contents. */
export function addableKeys(
  filters: PaymentFilters,
  added: readonly FilterKey[]
): FilterKey[] {
  const visible = visibleKeys(filters, added);
  return FILTERS.filter((def) => !visible.includes(def.key)).map(
    (def) => def.key
  );
}

/** Whether anything at all is applied, search included. */
export function hasActiveFilters(filters: PaymentFilters): boolean {
  return (
    Boolean(filters.email.trim()) ||
    FILTERS.some((def) => def.value(filters) !== null)
  );
}

/**
 * How much of the result set is on screen.
 *
 * Shared between this block's two tables, which asked the same question with
 * the same arithmetic and differed only in the noun.
 *
 * It is not what the pagination status says: `Page 2 of 2` reads the same
 * whether that page holds ten rows or the three left over. Nor is it the
 * selection count — `SelectionBar` already states that, at every width, where
 * `TablePaginationInfo` is `hidden lg:block`.
 *
 * Deliberately a block file rather than a library prop. `TablePaginationInfo`
 * already accepts `children`, which is the composition answer, and the whole
 * of the rest is two lines of arithmetic and a plural.
 */
export function ResultSummary({
  noun,
  pageIndex,
  pageSize,
  rowCount,
  totalCount,
}: {
  /** Singular and plural, because English will not derive one from the other. */
  noun: [string, string];
  pageIndex: number;
  pageSize: number;
  rowCount: number;
  totalCount: number;
}) {
  if (totalCount === 0) {
    return null;
  }

  const first = pageIndex * pageSize + 1;
  const last = pageIndex * pageSize + rowCount;

  return (
    <>
      Showing {first}–{last} of {totalCount}{" "}
      {totalCount === 1 ? noun[0] : noun[1]}
    </>
  );
}

"use client";

import { cn } from "@/lib/utils";

export interface SeriesDef {
  /** Slot 1-5 in the chart ramp. Omit to take the position in the list. */
  color?: number;
  key: string;
  label: string;
  /**
   * Use a named token instead of a ramp slot, e.g. `"muted-foreground"`.
   *
   * The escape hatch matters: an "Other" or "Unclassified" band is not a
   * category, and giving it a categorical hue claims one exists where there is
   * only missing evidence.
   */
  token?: string;
}

/**
 * The single place a series' colour is decided.
 *
 * Both the mark and the legend swatch resolve through this, so they cannot
 * disagree — a legend that says one thing while the band says another is worse
 * than no legend.
 */
export function seriesColor(item: SeriesDef, index: number): string {
  if (item.token) {
    return `var(--${item.token})`;
  }
  return `var(--chart-${item.color ?? (index % 5) + 1})`;
}

interface SeriesLegendProps {
  hidden: ReadonlySet<string>;
  onToggle: (key: string) => void;
  series: readonly SeriesDef[];
}

export function SeriesLegend({ hidden, onToggle, series }: SeriesLegendProps) {
  const visible = series.filter((item) => !hidden.has(item.key)).length;

  return (
    <ul className="flex flex-wrap items-center gap-x-4 gap-y-1">
      {/* Rendered from `series`, never from recharts' payload: the payload
          drops hidden entries, which would give you a chart you can narrow and
          then never widen again. */}
      {series.map((item, index) => {
        const off = hidden.has(item.key);
        // An empty chart is not a view of anything, and a reader cannot tell it
        // from "no data" — so the last visible series refuses to switch off.
        const locked = !off && visible === 1;

        return (
          <li key={item.key}>
            <button
              aria-pressed={!off}
              className={cn(
                "inline-flex cursor-pointer items-center gap-1.5 rounded-sm text-xs transition-colors focus-visible:outline-2 focus-visible:outline-ring/50 focus-visible:outline-offset-2",
                off
                  ? "text-muted-foreground line-through opacity-60"
                  : "text-foreground",
                locked && "cursor-not-allowed"
              )}
              disabled={locked}
              onClick={() => onToggle(item.key)}
              title={
                locked ? "At least one series has to stay visible" : undefined
              }
              type="button"
            >
              <span
                aria-hidden="true"
                className="size-2.5 shrink-0 rounded-[2px]"
                style={{ backgroundColor: seriesColor(item, index) }}
              />
              {item.label}
            </button>
          </li>
        );
      })}
    </ul>
  );
}

"use client";

import { useEffect, useState } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

/**
 * Whether the viewer has asked for reduced motion.
 *
 * `base.css` already zeroes CSS animation under `prefers-reduced-motion`, but
 * recharts animates SVG *attributes* from JavaScript, which no stylesheet can
 * reach. So the library's central reduced-motion rule silently does not cover
 * charts, and this is the only place that can close the gap — pass the result
 * to `isAnimationActive`.
 *
 * Starts `false` deliberately: guessing `true` on the server and correcting on
 * the client would be a hydration mismatch, so one frame of motion is the
 * better trade.
 */
export function useReducedMotion(): boolean {
  const [reduced, setReduced] = useState(false);

  useEffect(() => {
    const media = window.matchMedia(QUERY);
    setReduced(media.matches);

    const onChange = (event: MediaQueryListEvent) => setReduced(event.matches);
    media.addEventListener("change", onChange);
    return () => media.removeEventListener("change", onChange);
  }, []);

  return reduced;
}
